export type ParsedRefundInstruction<
  TProgram extends string = typeof QELARIX_QLC_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    operator: TAccountMetas[0];
    config: TAccountMetas[1];
    chargeReceipt: TAccountMetas[2];
    member: TAccountMetas[3];
    memberTokenAccount: TAccountMetas[4];
    qlcMint: TAccountMetas[5];
    vault: TAccountMetas[6];
    vaultAuthority: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
  };
  data: RefundInstructionData;
};

export function parseRefundInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRefundInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      operator: getNextAccount(),
      config: getNextAccount(),
      chargeReceipt: getNextAccount(),
      member: getNextAccount(),
      memberTokenAccount: getNextAccount(),
      qlcMint: getNextAccount(),
      vault: getNextAccount(),
      vaultAuthority: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getRefundInstructionDataDecoder().decode(instruction.data),
  };
}
